import { _decorator, Component, Node } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('PopupManager')
export class PopupManager extends Component{
    private static _instance: PopupManager;
    public static get instance(): PopupManager {
        if (!this._instance) {
            this._instance = new PopupManager();
        }
        return this._instance;
    }
    @property(Node)
    private _settingPopup: Node = null;
    @property(Node)
    private _resultPopup: Node = null;
    @property(Node)
    private _popupNode: Node = null;

    public set popupNode(node: Node) {
        this._popupNode = node;
    }

    public get popupNode(): Node {
        return this._popupNode;
    }

    public showPopup() {
        if (this._popupNode) {
            this._popupNode.active = true;
        }
    }

    public hidePopup() {
        if (this._popupNode) {
            this._popupNode.active = false;
        }
    }

    public togglePopup() {
        if (this._popupNode) {
            this._popupNode.active = !this._popupNode.active;
        }
    }

}

